            delay = base_delay
            while True:
                attempt += 1
                try:
                    return func(*args, **kwargs)
                except exceptions:
                    if attempt >= max_attempts:
                        raise
                    sleep_for = min(delay, max_delay)
                    time.sleep(sleep_for + random.uniform(0, sleep_for * 0.1))
                    delay *= 2
        return wrapper
